function normalizeKey(key) {
  return String(key || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function flatten(value, out = {}) {
  if (Array.isArray(value)) {
    value.forEach((item) => flatten(item, out));
    return out;
  }

  if (!value || typeof value !== 'object') return out;

  const obj = value;
  const candidateKey = [obj.name, obj.label, obj.key, obj.id].find((v) => typeof v === 'string');
  const candidateValue = obj.value ?? obj.answer ?? obj.response;

  if (candidateKey && candidateValue !== undefined && typeof candidateValue !== 'object') {
    out[normalizeKey(candidateKey)] = candidateValue;
  }

  for (const [key, child] of Object.entries(obj)) {
    if (child !== undefined && child !== null && typeof child !== 'object') {
      out[normalizeKey(key)] = child;
    } else {
      flatten(child, out);
    }
  }

  return out;
}

function pick(fields, names) {
  for (const name of names) {
    const value = fields[normalizeKey(name)] ?? fields[name];
    if (value !== undefined && value !== null && String(value).trim()) {
      return String(value).trim();
    }
  }
  return '';
}

function amount(value) {
  const n = Number(String(value || '').replace(/[₹,\s]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

function yesNo(value) {
  return ['true', 'yes', 'y', 'active', '1'].includes(String(value || '').trim().toLowerCase());
}

const fields = flatten($json);

const customer_id = pick(fields, ['customer_id']);
const spreadsheet_id = pick(fields, ['spreadsheet_id']);
const tab_name = pick(fields, ['tab_name']);
const bank = pick(fields, ['bank']);
const locker_id = pick(fields, ['locker_id', 'locker id']);
const size = pick(fields, ['size']).toUpperCase();

if (!customer_id) throw new Error('Missing customer_id URL parameter');
if (!spreadsheet_id) throw new Error('Missing spreadsheet_id URL parameter');
if (tab_name !== 'Locker') throw new Error(`Invalid tab_name: ${tab_name}`);
if (!bank) throw new Error('Missing bank');
if (!locker_id) throw new Error('Missing locker_id');
if (!['S', 'M', 'L', 'XL'].includes(size)) throw new Error(`Invalid locker size: ${size}`);

const bank_address = [
  pick(fields, ['bank_address', 'address_bank_address', 'address']),
  pick(fields, ['city_bank_address', 'city']),
  pick(fields, ['state_province_bank_address', 'state_province', 'state']),
  pick(fields, ['zip_postal_code_bank_address', 'zip_postal_code', 'postal_code', 'zip']),
  pick(fields, ['country_bank_address', 'country'])
].filter(Boolean).join(', ');

return {
  json: {
    customer_id,
    spreadsheet_id,
    tab_name,
    source: pick(fields, ['source']) || 'wealthyo_dashboard',
    entry_date: pick(fields, ['entry_date']) || new Date().toISOString().slice(0, 10),
    bank,
    locker_id,
    size,
    locker_open_date: pick(fields, ['locker_open_date', 'locker open date']),
    is_active: yesNo(pick(fields, ['is_active', 'is_active?', 'is active'])),
    yearly_maintenance_fee: amount(pick(fields, ['yearly_maintenance_fee', 'yearly maintenance fee'])),
    deposit_amount: amount(pick(fields, ['deposit_amount', 'deposit amount'])),
    access_list: pick(fields, ['access_list', 'access list']),
    bank_address
  }
};
